// ── Primitive ops ─────────────────────────────────────────────────────────────

// Conv1D 'same' padding, ReLU fused in.  W layout: [k*C_in*C_out + c*C_out + o]
static inline void _conv1d(float* out, const float* in,
                            int T, int C_in, int C_out,
                            const float* W, const float* b, int K) {
    const int pad = K / 2;
    for (int t = 0; t < T; t++) {
        for (int o = 0; o < C_out; o++) {
            float s = b[o];
            for (int k = 0; k < K; k++) {
                const int ti = t + k - pad;
                if (ti >= 0 && ti < T)
                    for (int c = 0; c < C_in; c++)
                        s += in[ti * C_in + c] * W[k * C_in * C_out + c * C_out + o];
            }
            out[t * C_out + o] = s > 0.0f ? s : 0.0f;   // ReLU
        }
    }
}

// MaxPool1D  pool_size=2, stride=2
static inline void _maxpool1d(float* out, const float* in, int T, int C) {
    const int T2 = T / 2;
    for (int t = 0; t < T2; t++)
        for (int c = 0; c < C; c++) {
            float a = in[(2*t)  *C+c], bb = in[(2*t+1)*C+c];
            out[t*C+c] = a > bb ? a : bb;
        }
}

// GlobalAveragePool1D
static inline void _gap1d(float* out, const float* in, int T, int C) {
    for (int c = 0; c < C; c++) {
        float s = 0.0f;
        for (int t = 0; t < T; t++) s += in[t*C+c];
        out[c] = s / T;
    }
}

// Dense layer.  W layout: [i*C_out + o]
static inline void _dense(float* out, const float* in,
                           int C_in, int C_out,
                           const float* W, const float* b, bool relu) {
    for (int o = 0; o < C_out; o++) {
        float s = b[o];
        for (int i = 0; i < C_in; i++) s += in[i] * W[i*C_out+o];
        out[o] = (relu && s < 0.0f) ? 0.0f : s;
    }
}

// ── Full forward pass ─────────────────────────────────────────────────────────
// input : float[150]  — per-window z-scored, layout [timestep*3 + channel]
// returns: P(circle) in [0,1]
static float gesture_cnn_predict(const float* input) {
    static float b1[50*8],  b2[25*8];
    static float b3[25*16], b4[12*16], b5[12*16];
    static float gap[16], d1[8], d2[1];

    _conv1d   (b1,  input, 50,  3,  8,  CNN_CONV1_W, CNN_CONV1_B, 5);
    _maxpool1d(b2,  b1,    50,  8);
    _conv1d   (b3,  b2,    25,  8,  16, CNN_CONV2_W, CNN_CONV2_B, 3);
    _maxpool1d(b4,  b3,    25,  16);
    _conv1d   (b5,  b4,    12,  16, 16, CNN_CONV3_W, CNN_CONV3_B, 3);
    _gap1d    (gap, b5,    12,  16);
    _dense    (d1,  gap,   16,  8,  CNN_DENSE1_W, CNN_DENSE1_B, true);
    _dense    (d2,  d1,     8,  1,  CNN_DENSE2_W, CNN_DENSE2_B, false);

    return 1.0f / (1.0f + expf(-d2[0]));   // sigmoid → P(circle)
}
